<?php require_once __DIR__ . '/../../includes/layout.php'; require_role(['Student','Admin']); $student=row('SELECT * FROM students WHERE user_id=?',[$_SESSION['user_id']]) ?: row('SELECT * FROM students LIMIT 1'); render_header('My Grades'); ?><div class="page-title"><div><h1>My Grades</h1><p>Academic performance and GPA.</p></div></div><div class="panel"><table class="table"><thead><tr><th>Subject</th><th>Prelim</th><th>Midterm</th><th>Final</th><th>GPA</th><th>Remarks</th></tr></thead><tbody><?php foreach(rows('SELECT g.*,sub.code,sub.title FROM grades g JOIN subjects sub ON sub.id=g.subject_id WHERE g.student_id=?',[$student['id']]) as $g): ?><tr><td><?= e($g['code'].' - '.$g['title']) ?></td><td><?= e($g['prelim']) ?></td><td><?= e($g['midterm']) ?></td><td><?= e($g['final']) ?></td><td><?= e($g['gpa']) ?></td><td><?= e($g['remarks']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php render_footer(); ?>
